<?php
require_once __DIR__.'/../includes/bootstrap.php';require_once __DIR__.'/../includes/view_helpers.php';require_login();$admin=current_user()['role']==='admin';$owner=$admin?null:(int)current_user()['user_id'];$filter=(int)($_GET['project_id']??0);
$projectsSql='SELECT project_id,name FROM projects'.($admin?'':' WHERE user_id=?').' ORDER BY name';$pq=$pdo->prepare($projectsSql);$pq->execute($admin?[]:[$owner]);$projects=$pq->fetchAll();$runs=scan_runs($pdo,null,$owner);if($filter){$runs=array_values(array_filter($runs,fn($r)=>(int)$r['project_id']===$filter));if(!$admin){$allowed=array_column($projects,'project_id');if(!in_array($filter,array_map('intval',$allowed),true)){http_response_code(404);exit('Project not found.');}}}
page_header('Vulnerability Monitoring');?>
<div class="page-heading"><div><span class="eyebrow">SECURITY VISIBILITY</span><h1>Vulnerability Monitoring</h1><p>Review completed dependency scan runs, rather than individual database rows.</p></div></div>
<form class="card card-body mb-3" method="get"><div class="row g-2 align-items-end"><div class="col-md-5"><label class="form-label">Filter by project</label><select class="form-select" name="project_id"><option value="0">All projects</option><?php foreach($projects as $p):?><option value="<?=$p['project_id']?>" <?=$filter===(int)$p['project_id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select></div><div class="col-auto"><button class="btn btn-outline-primary">Apply filter</button></div></div></form>
<div class="card"><div class="card-header"><strong>Scan runs</strong><span class="small text-secondary"><?=count($runs)?> runs</span></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Project</th><?php if($admin):?><th>Owner</th><?php endif;?><th>Date</th><th>Dependencies</th><th>Findings</th><th>Critical</th><th>High</th><th>Medium</th><th>Low</th><th>Unclassified</th><th>Compliance</th><th></th></tr></thead><tbody><?php foreach($runs as $r):$c=compliance_for_scan($pdo,(int)$r['project_id'],$r);?><tr><td><?=e($r['project_name'])?></td><?php if($admin):?><td><?=e($r['owner'])?></td><?php endif;?><td><?=e($r['scanned_at'])?></td><td><?=e($r['dependencies_checked'])?></td><td><?=e($r['findings'])?></td><td><?=e($r['critical'])?></td><td><?=e($r['high'])?></td><td><?=e($r['medium'])?></td><td><?=e($r['low'])?></td><td><?=e($r['unclassified'])?></td><td><?=compliance_badge($c['status'])?></td><td><a class="btn btn-sm btn-outline-primary" href="<?=e(url('scan.php?id='.$r['run_id']))?>">Details</a> <?=report_action($pdo,(int)$r['run_id'],$admin)?></td></tr><?php endforeach;?><?php if(!$runs):?><tr><td colspan="<?=$admin?12:11?>" class="empty-state">No scan runs found.</td></tr><?php endif;?></tbody></table></div></div><?php require APP_ROOT.'/includes/footer.php';?>
